//! Writes `generated.txt` into `OUT_DIR`, which the library reads at run
//! time through the path compiled into it.

fn main() {
    let out = std::env::var_os("OUT_DIR").expect("cargo sets OUT_DIR");
    let file = std::path::Path::new(&out).join("generated.txt");
    std::fs::write(&file, "generated by outdir-dep").expect("write generated.txt");
}
